const stock=$('Analizar stock en transito').all().map(i=>i.json);
const efectivas=$('Analizar ODT efectivas').all().map(i=>i.json);
const mapa=new Map();
for(const r of efectivas.filter(r=>r.valido)){
  const anterior=mapa.get(r.clave_operativa);
  if(!anterior||r.cantidad_validacion_recepcion>anterior.cantidad_validacion_recepcion)mapa.set(r.clave_operativa,r);
}
const detalle=stock.filter(r=>r.valido).map(r=>{
  const e=mapa.get(r.clave_operativa);
  const recibidaEfectiva=e?e.cantidad_validacion_recepcion:null;
  const recibidaControl=Math.max(r.cantidad_validacion_recepcion,recibidaEfectiva??0);
  const pendiente=Math.max(r.cantidad_validacion_despacho-recibidaControl,0);
  let estado;
  if(!e)estado=r.cantidad_pendiente_transito>0?'PENDIENTE_SIN_EFECTIVA':'RECIBIDA_SIN_REGISTRO_EFECTIVA';
  else if(!pendiente&&r.cantidad_pendiente_transito>0)estado='EFECTIVA_CONFIRMA_INGRESO';
  else if(!pendiente)estado='RECEPCION_CONFIRMADA';
  else if(recibidaControl>0)estado='RECEPCION_PARCIAL_CONFIRMADA';
  else estado='PENDIENTE';
  return {fecha_documento:r.fecha_documento,numero_documento:r.numero_documento,sucursal_desde_nombre:r.sucursal_desde_nombre,sucursal_hacia_nombre:r.sucursal_hacia_nombre,clave:r.clave,nombre:r.nombre,cantidad_despachada:r.cantidad_validacion_despacho,cantidad_recibida_stock:r.cantidad_validacion_recepcion,cantidad_recibida_efectiva:recibidaEfectiva,cantidad_pendiente_stock:r.cantidad_pendiente_transito,cantidad_pendiente_control:pendiente,encontrada_en_efectivas:Boolean(e),estado_control:estado};
});
const st=$('Resumen stock en transito').first().json;
const ef=$('Resumen ODT efectivas').first().json;
if(st.estado!=='VALIDACION_OK'||ef.estado!=='VALIDACION_OK')throw new Error('No se persisten reportes con errores de validacion.');
const cuenta=estado=>detalle.filter(r=>r.estado_control===estado).length;
const resumenControl={estado:'CONTROL_ODT_OK',criterio_cruce:'NumeroDocumento + Clave',lineas_controladas:detalle.length,lineas_encontradas_en_efectivas:detalle.filter(r=>r.encontrada_en_efectivas).length,lineas_pendientes_sin_efectiva:cuenta('PENDIENTE_SIN_EFECTIVA'),lineas_efectiva_confirma_ingreso:cuenta('EFECTIVA_CONFIRMA_INGRESO'),lineas_recepcion_confirmada:cuenta('RECEPCION_CONFIRMADA'),unidades_pendientes_segun_stock:detalle.reduce((t,r)=>t+r.cantidad_pendiente_stock,0),unidades_pendientes_segun_control:detalle.reduce((t,r)=>t+r.cantidad_pendiente_control,0),resumen_stock_transito:st,resumen_odt_efectivas:ef,detalle_control:detalle};
const sqlTexto=valor=>"'" + String(valor).replace(/'/g,"''") + "'";
const sqlJson=valor=>"'" + JSON.stringify(valor).replace(/'/g,"''") + "'::jsonb";
const idEjecucion=String($execution.id);
const observadoEn=new Date().toISOString();
const reportes=[
  {tipo:'stock_en_transito',resumen:st,lineas:stock,archivo:$('Validar stock en transito').first().json},
  {tipo:'odt_efectivas_35_dias',resumen:ef,lineas:efectivas,archivo:$('Validar ODT efectivas').first().json}
];
return reportes.map((reporte,indice)=>{
  const archivo={id:reporte.archivo.id,nombre:reporte.archivo.name,modificado_en:reporte.archivo.modifiedTime};
  const query='select * from centum_sync.ingestar_snapshot_odt('+sqlTexto(idEjecucion)+', '+sqlTexto(observadoEn)+'::timestamptz, '+sqlTexto(reporte.tipo)+', '+sqlJson(archivo)+', '+sqlJson(reporte.resumen)+', '+sqlJson(reporte.lineas)+');';
  return {json:{query,id_ejecucion:idEjecucion,tipo_reporte:reporte.tipo,observado_en:observadoEn,registros_preparados:reporte.lineas.length,resumen_control:indice===0?resumenControl:null}};
});

const reportes=$input.all().map(i=>i.json);
const tipos=new Set(reportes.map(r=>r.tipo_reporte));
const completada=reportes.length===2
  && tipos.has('stock_en_transito')
  && tipos.has('odt_efectivas_35_dias')
  && reportes.some(r=>r.ejecucion_completada===true||r.ejecucion_completada==='true');
if(!completada)throw new Error('La ejecucion ODT no completo la persistencia de los dos reportes.');
const resumen=$('Cruzar y resumir ODT').first().json.resumen_control;
return [{json:{...resumen,estado:'CONTROL_ODT_OK',persistencia:{estado:'COMPLETADA',id_ejecucion:String($execution.id),reportes:reportes.map(r=>({id_importacion:r.id_importacion,tipo_reporte:r.tipo_reporte,importacion_nueva:r.importacion_nueva,registros_persistidos:r.registros_persistidos,documentos_persistidos:r.documentos_persistidos,reportes_procesados:r.reportes_procesados,ejecucion_completada:r.ejecucion_completada}))}}}];
